import type Stripe from "stripe";
import { markInvoicePaid, markInvoiceFinalized, recordRefund, syncCustomer } from "./sync.js";
import { logger } from "../logger.js";

type Handler = (object: Stripe.Event.Data.Object) => Promise<void>;

const handlers: Partial<Record<Stripe.Event.Type, Handler>> = {
  "invoice.paid": (o) => markInvoicePaid(o as Stripe.Invoice),
  "invoice.finalized": (o) => markInvoiceFinalized(o as Stripe.Invoice),
  "charge.refunded": (o) => recordRefund(o as Stripe.Charge),
  "customer.updated": (o) => syncCustomer(o as Stripe.Customer),
};

export async function handleStripeEvent(event: Stripe.Event): Promise<void> {
  const handler = handlers[event.type];
  if (!handler) {
    logger.debug({ type: event.type }, "unhandled stripe event");
    return;
  }
  await handler(event.data.object);
}

from decimal import Decimal
from pathlib import Path

import gpxpy
from django.core.management.base import BaseCommand, CommandError
from django.db import transaction

from trails.models import TrackPoint, Trail


class Command(BaseCommand):
    help = "Import every .gpx file in a folder as a Trail with its TrackPoints"

    def add_arguments(self, parser):
        parser.add_argument("folder", type=Path)

    def handle(self, *args, folder: Path, **opts):
        if not folder.is_dir():
            raise CommandError(f"{folder} is not a directory")
        for path in sorted(folder.glob("*.gpx")):
            with path.open() as fh:
                gpx = gpxpy.parse(fh)
            points = [p for track in gpx.tracks for seg in track.segments for p in seg.points]
            if not points:
                self.stderr.write(f"skip {path.name}: no track points")
                continue
            with transaction.atomic():
                trail = Trail.objects.create(
                    name=gpx.name or path.stem,
                    distance_km=Decimal(gpx.length_2d() / 1000).quantize(Decimal("0.01")),
                )
                TrackPoint.objects.bulk_create(
                    TrackPoint(trail=trail, seq=i, lat=p.latitude, lon=p.longitude, ele=p.elevation)
                    for i, p in enumerate(points)
                )
            self.stdout.write(self.style.SUCCESS(f"{path.name}: {len(points)} points"))

